#!/usr/bin/env python3
"""Full German per-passage gist for The Refuge (book 8). Draft, pending native review."""
import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "content", "gist", "the-refuge", "de.json")
G = {
1: "Es ist die schlimmste Nacht des Winters, und der Whiteout kommt rasch mit der Dunkelheit herab. Schnee treibt am einzigen Fenster vorbei, und der Berg verliert sich im Weiß. Dann stürzt die alte Marta, die diese Hütte seit dreißig Wintern hütet, von der Dachbodenleiter und kommt nicht mehr hoch. Der Ofen ist niedrig, die Lampe aus, und keine Mannschaft kann vor dem Morgen heraufsteigen. Die Hütte zu halten, liegt jetzt an dir.",
2: "Du holst, was die Hütte hergibt: einen Kanister Lampenöl, Streichhölzer, eine gute Sturmlampe, einen Arm voll trockenes Holz. Draußen heult der Wind, und die Kälte dringt gerade unter der Tür durch. Schnee kriecht schon weiß darunter herein. Du musst entscheiden, was zu tun ist, und zwar schnell.",
3: "Du versuchst das Funkgerät. Es rauscht und knackt, dann kommt endlich Kerrs Stimme vom Posten im Tal durch. Keine Mannschaft kann vor dem Morgen heraufsteigen, sagt er — nicht in so einen Whiteout. Halte den Ofen am Brennen und die Lampe im Fenster, sagt er, und halte durch, wenn du irgend kannst.",
4: "Du erreichst Marta am Fuß der Leiter und machst sie warm und bequem. Aber die Hütte ist kalt und das Fenster dunkel. Schutz allein reicht nicht. Wer da draußen festsitzt, braucht die Lampe an und den Ofen in Gang. Du brauchst Brennstoff, einen Plan und einen klaren Kopf.",
5: "Du trittst in den Sturm hinaus. Der Wind reißt dich fast von den Füßen, und der Schnee treibt flach und weiß. Die Kälte drückt auf den ganzen Berg wie eine Hand. Dann, weit unten am Hang, siehst du es: ein kleines Licht, das sich bewegt, wo heute Nacht niemand sein sollte.",
6: "Du zwingst dich zum Nachdenken. Erst Ofen und Lampe in Gang bringen und den Rest später. Oder zu Marta und den Wanderern im Schlafsaal gehen. Oder das Tal wecken und mehr Hände holen. Jede Wahl kostet Zeit, die du nicht hast — und draußen arbeitet die Kälte schon an jedem, der festsitzt.",
8: "Die Kälte legt sich wie ein Gewicht auf deine Brust. Du denkst an die Menschen da draußen: ein verlorener Wanderer am Hang, und die Hütte die einzige Wärme meilenweit. Bleibt das Fenster noch lange dunkel, holt die Kälte sie bis zum Morgen. Das ist keine Angst; das ist eine Tatsache. Niemand sonst kommt. Du bist es, heute Nacht, oder niemand.",
9: "Doune stößt das Brennstofflager auf und hebt die Lampe. Drinnen: ein Fass Öl, Streichhölzer, Bündel trockenes Holz, Sackleinen. »Nimm, was du brauchst«, sagt er. »Ich bleibe hier am Funk und rufe, wen ich kann.« Er ist ein fester Mann, und eine solche Nacht zeigt es.",
10: "Du klopfst die Pritschen entlang, und der alte Breck öffnet, bleich vor Kälte. Sein kleiner Ofen ist ausgegangen, seine Streichhölzer sind alle, und seine Hände zittern zu sehr, um eins anzureißen. »Ich kriege es nicht an«, sagt er. Vor dir liegt eine lange, harte Nacht. Aber er ist hier, voller Angst, und dich bittet er.",
11: "Du gehst geradewegs zum Ofen und zündest, was du kannst. Ein Streichholz, ein Aufflammen von Zunder, eine niedrige Flamme, die im Rost fasst. Aber das Feuer ist dünn und die Lampe flackert. Ohne richtigen Brennstoff halten sie keine Stunde. Du kannst sie nicht einfach anzünden und hoffen.",
12: "Du gehst von Tür zu Tür mit denselben Worten. Bring Holz für den Ofen. Hilf mit. Hilf mir, die Lampe im Fenster zu halten. Manche wenden sich ab und schließen. Aber ein paar ziehen den Mantel an und treten in die Kälte. Heute Nacht reichen ein paar zum Anfang.",
13: "Du übernimmst den Brennstoff und das trockene Holz selbst. Das Fass ist schwer, und jeder Tropfen Öl zählt jetzt. Gut genutzt, hält es Ofen und Lampe die ganze Nacht; vergeudet, wird die Hütte vor dem Morgen kalt und dunkel. Also drückst du es an dich und gehst an die Arbeit.",
14: "Du nimmst nur eine Sturmlampe und etwas Zunder. Zum Sehen und zum Entfachen einer Flamme. Aber nicht den Ofen selbst, und du hast keinen richtigen Brennstoff beiseitegelegt. Du brauchst welchen, und bald. Sonst bleibt das Fenster dunkel und die Kälte gewinnt.",
15: "Der alte Doune ist diesen Berg im Dunkeln öfter gegangen als irgendwer sonst. »Bleib weg von der Wächte über dem Kar«, sagt er. »Sie sieht aus wie eine Abkürzung. Ist sie nicht — es ist ein langer Sturz.« Er warnt dich auch vor Vane, diesem lächelnden Mann von der Firma. »Pass auf deinen Brennstoff, halte die Lampe — das ist die ganze Arbeit heute Nacht.«",
16: "Du bringst den Ofen zum Ziehen und setzt Breck mit einer Decke daneben. Nach und nach lässt sein Zittern nach. »Gott segne dich«, sagt er und drückt deine Hand fest. Du versprichst, vor dem Morgen wieder nach ihm zu sehen. Dann gehst du zurück in die Kälte und zum dunklen Fenster.",
17: "Die Hütte warm und hell zu halten kommt zuerst. Der Rest kann einen Moment warten. Aber wie? Du könntest erst richtigen Brennstoff aus dem Lager holen. Oder geradewegs zum Ofen und zur Lampe.",
18: "Die Arbeit zehrt an dir. Die Beine brennen, die Brust keucht, und der Wind kämpft bei jedem Schritt gegen dich. Du bist an deiner Grenze, und du weißt es. Gehst du hier zu Boden, bleibt niemand, der die Hütte hält. Also geh langsam, geh vorsichtig.",
19: "Das Tal erwacht, und die Leute beginnen sich zu rühren. Ein Mann schultert ein Fass Brennstoff. Eine Frau zieht trockenes Holz und Stirnlampen hervor. Tür um Tür nimmt ein Plan Gestalt an. Du bist nicht mehr allein. Und das ändert alles.",
20: "Niemand rührt sich. Die Türen bleiben zu, die Gesichter wenden sich von den Fenstern ab. Sie haben Angst, und ängstliche Menschen verstummen. Du kannst sie nicht zwingen, da hinauszusteigen. Also gehst du allein weiter. So ist es härter. Aber die Leute da draußen können nicht auf sie warten.",
21: "Der Ofen zieht und die Lampe steht im Fenster. Jetzt zum fernen Lager und dem Brennstoffdepot. Zwei Wege führen hin. Der lange Pfad ums Kar herum ist sicher, aber langsam. Die Wächte geradeaus ist schnell. Aber in so einer Nacht könnte sie nachgeben.",
22: "Du nimmst die Worte des alten Doune zu Herzen. Pass auf den Brennstoff auf. Weg von der Wächte. Trau Vane nicht. Und halte die Lampe im Fenster über allem. Einfacher Rat, und gut. Bleibt nur, ihn zu befolgen.",
23: "Die gute Tat festigt dich. Jemandem zu helfen festigt seltsamerweise auch dich. Der Kopf klarer, die Hände sicherer. Eine harte Nacht steht noch bevor. Aber du fühlst dich ihr gewachsen.",
24: "Ein Mann tritt aus dem Schnee, eine Laterne in der Faust — Vane. Er hat Brennstoff zu verkaufen und Arme zu leihen, und er lächelt zu leicht. »Die Hütte ist heute Nacht nicht wirklich deine Sache, Freund«, sagt er. Du hast seinesgleichen schon gesehen.",
25: "Du führst eine kleine Schar zur Hütte hinauf. Zusammen fühlt ihr euch stärker. Sie tragen Brennstoff, Holz und Fackeln. »Hier entlang!«, rufst du in den Wind, und sie kommen. Das tut gut, in so einer harten Stunde.",
26: "Der Pfad ist schwarz und hart, der Wind fegt ihn entlang, nirgends Schutz. Aber er ist fest unter den Füßen, und er führt, wohin du musst. Also gehst du weiter, Schritt um Schritt.",
27: "Die Wächte würde den Weg halbieren, das Lager gleich dahinter. Aber der Rand ist dünn und der Schnee locker über einem langen, tödlichen Sturz. Doune sagte, du sollst wegbleiben — und er scherzte nicht.",
28: "Du setzt den Fuß auf die Wächte, und sofort fühlt es sich falsch an. Der Abgrund wartet darunter, schwarz, fern, eisig. Jeder Schritt ist ein Wagnis — und du bist darauf, allein. Kein Zurück, einmal begonnen.",
29: "Das Holz ist feucht und fängt nicht. Es gibt nur eine niedrige, rauchige Flamme. Wenig Nutzen bei so einer Kälte. Du musst dich damit behelfen. Oder zum Lager zurück für trockenes Holz.",
30: "Der Pfad läuft weiter am Hang, die Kälte Stunde um Stunde tiefer. Darunter eine dunkle Hütte, ohne Feuer. Voraus scheint die stille, harte Luft dich zurückzudrängen. Und da ist ein Wegweiser, halb im gefrorenen Schnee vergraben.",
31: "Ein Wanderer ist im Schnee zu Boden gegangen und kommt nicht hoch. Die Kälte packt ihn schon. Hältst du an, verlierst du Zeit, die du nicht hast. Tust du es nicht, übersteht er die Stunde vielleicht nicht.",
32: "Eine Gruppe sitzt in einer eisigen Hütte fest — kein Feuer, keine Lampe, ein Kind weint im Dunkeln. Die Erwachsenen sehen dich an, müde, ohne Hoffnung. Du hast eine Lampe und einen Mantel. Nicht viel, aber mehr als sie.",
33: "Du drängst durch das Schlimmste der Kälte, jeder Schritt ein Kampf, der Schnee sticht dir ins Gesicht. Vor dir liegen Entscheidungen. Vielleicht Vane. Dieses seltsame Licht am Hang. Oder geradewegs zur Hütte.",
34: "Du hilfst dem Wanderer auf die Beine und wärmst ihn, so gut du kannst. Seine Augen füllen sich. Er drückt dir ein Paar trockene Fäustlinge in die Hände. »Nimm sie«, sagt er, »für deine Mühe.« Eine Kleinigkeit — aber frei gegeben. Du nimmst sie und gehst weiter.",
35: "Du kannst nicht bleiben — aber sie auch nicht zurücklassen. Also versprichst du, Hilfe zu schicken. »Haltet durch!«, rufst du. »Bleibt warm, bleibt zusammen — ich vergesse euch nicht.« Und du meinst es. Dann wendest du dich und gehst.",
36: "Das Tal zündet ein großes Signalfeuer am Hügel an — ein Fass Holz in Flammen, das Licht und Wärme in den Sturm wirft. Man drängt sich darum, die Alten und Schwachen ganz nah. Es ist nicht die Nacht gewonnen. Aber es ist echte Wärme, und ein Anfang.",
37: "Hütte um Hütte wird das ängstliche Tal zu einem arbeitenden. Jeder hat eine Aufgabe: einer hütet das Feuer, einer trägt Holz, einer wacht über den Hang. Angst wird zu Tun. Und Tun schlägt Warten, jedes Mal.",
38: "Die lange Kälte nagt an deinem Willen. Eine kleine Stimme sagt: hör auf, geh rein, ruh dich aus — niemand würde es dir verübeln, es wäre so leicht. Aber du denkst an die Leute am Hang. Und du verjagst die Stimme. Noch nicht. Nicht, solange sie zu erreichen sind.",
39: "Du erreichst den alten Wegweiser, aber der Schnee hat ihn vergraben und halb umgeworfen. Kaum zu lesen. Ein Arm zeigt den Pfad entlang. Der andere über den Hang. Welcher Weg? Du musst raten, und richtig raten.",
40: "Vane wendet dir sein breites, leichtes Lächeln zu. »Kalte Arbeit, das«, sagt er. »Ich habe Brennstoff zu verkaufen und Arme zu leihen — und die Hütte ist heute Nacht nicht wirklich deine Sache, Freund.« Seine Laterne schwingt. Sein Lächeln erreicht nie die Augen.",
41: "Das Angebot ist ein Haken, und du spürst ihn fassen. Er lehnt sich vor. »Die Hütte ist schon verloren«, sagt er leise. »Lass die Kälte sie holen — und es gibt einen Anteil für dich.« Es ist grausam, das zu sagen. Und es soll auf deine Angst wirken.",
42: "Du kehrst ihm den Rücken und überlässt ihn seinem kalten Handel. Es tut gut, wegzugehen. Er ruft dir nach, aber du drehst dich nicht um. Seinesgleichen findet immer jemanden, am Ende. Aber nicht dich, nicht heute Nacht.",
43: "Du nimmst seinen Brennstoff und seinen Handel. Deine Hände schließen sich darum, und etwas in dir weiß es schon. Sein Lächeln wird breiter. »Klug«, sagt er. Aber es fühlt sich gar nicht klug an. Es fühlt sich an wie eine Tür, die leise zugeht.",
44: "Du fragst ihn geradeheraus: was will er wirklich, und warum soll die Hütte fallen? Er lächelt und blickt in den Schnee. »Land ist billig nach einem schlechten Jahr«, sagt er. »So eine Nacht ist eine Gefälligkeit — für einen Käufer wie mich.«",
45: "Du trägst seinen Brennstoff zum Ofen. Aber als du ihn eingießt, erstickt die Flamme und spuckt. Er ist dünn, mit Wasser gestreckt — er nährt das Feuer nicht. Die Flamme sinkt, niedrig, braun, nutzlos.",
46: "Du öffnest den Kanister, und der Geruch trifft dich — dünn, sauer, mit Wasser gestreckt. Dieser Brennstoff nährt nie eine Flamme. Du hast gutes Geld gezahlt, und er ist wertlos. Der Zweifel in deinem Bauch hatte recht.",
47: "Du suchst ihn, aber Vanes Laterne ist schon fort, in den Schnee hinein. Er half dir nie. Er wartete auf den Sturm, die verlorene Nacht, das billige Land danach. Man hat dich getäuscht, ganz einfach.",
48: "Er ist weg, und der Hang ist leer — nur noch die Kälte, das Dunkel, und was du ihm für nichts gabst. Du hast eine harte Lektion gelernt. Und viel zu teuer bezahlt. Du gehst weiter mit weniger als zu Beginn.",
49: "Die verängstigten Leute drücken ihm ihr Geld in die Hände. Fäuste voll Scheine, Stimmen, die um Brennstoff flehen. Er nimmt es langsam, mit demselben Lächeln. Er wählt, wem er hilft, nach dem, wer am meisten zahlt.",
50: "Weit draußen auf der Wächte scheint die andere Seite endlich näher — oder doch nicht? Du bist dir nicht mehr sicher. Das Dunkel täuscht, und deine müden Augen auch. Und du bist weit von beiden Rändern.",
51: "Die Wächte, das Dunkel, der lange Sturz darunter — und ein Riss läuft unter deinem Fuß. Das ist der Moment. Mit dem Schnee ins Dunkel hinab. Oder zurückwerfen vom Riss, solange du noch kannst.",
52: "Du erreichst die andere Seite endlich, durchnässt, zitternd, die Hände wund — aber hinüber. Irgendwie hast du es geschafft. Jetzt musst du entscheiden: weiter, erschöpft, oder dem begegnen, was du auf der Wächte verloren hast.",
53: "Du wirfst dich zurück, solange du kannst — die harte, richtige Wahl. Du kriechst das letzte Stück auf Händen und Knien und erreichst festen Boden, erschüttert und langsam. Die Nacht ist nicht verloren. Aber sie kostete dich Zeit, die fehlen wird.",
54: "Du versuchst, ihren Ofen in Gang zu bringen, und blockierst den schlimmsten Zug mit Rucksäcken und einem alten Brett. Es hält ein wenig Kälte ab. Aber es gibt keine Lampe zu lassen, und die Nacht ist lange nicht vorbei.",
55: "Du gibst ihnen deinen Mantel und deine Lampe, und die Gruppe drängt sich um die kleine Flamme, Erleichterung in den Gesichtern. Das Kind hört endlich auf zu weinen. »Danke«, sagt die Mutter — und dann zeigt sie dir ein Licht, am Hang.",
56: "Ohne Mantel finden Kälte und Nässe dich schnell — die Zähne klappern, die Finger werden steif. Du gabst ihn weg, um zu helfen, und würdest es wieder tun. Aber dem Sturm ist das egal. Er beißt nur härter.",
57: "Ein Fremder winkt dich in eine erleuchtete Tür. »Nur eine Minute«, sagt er. »Raus aus der Kälte — schöpf Atem.« Es ist warm und trocken, und dein ganzer Körper fleht dich an zu bleiben. Aber so eine Minute gleitet schnell in eine Stunde.",
58: "Du drängst in den Sturm, bis auf die Knochen durchkältet. Die Kälte kämpft bei jedem Schritt. Die Augen tränen und brennen. Jeder Schritt ist eine kleine Schlacht. Aber du reihst sie aneinander, einen nach dem anderen, zur Hütte.",
60: "Jemand zeigt über den Hang: ein Wanderer ist dort hinausgegangen, allein, in Kälte und Dunkel. Draußen liegt nur Schnee und der lange, tödliche Sturz. Geht niemand ihm nach, kommt er vielleicht nicht zurück.",
61: "Du findest ihn am Hang, halb erfroren und verloren, die Kälte zerrt an ihm. Er scheint dein Gesicht nicht zu kennen. Du fasst ihn fest am Arm. »Komm mit mir«, sagst du. »Jetzt ist es gut. Ich hab dich.«",
62: "Du kannst nicht alles tun, und die Hütte braucht dich am meisten. Also schickst du einen anderen hinterher und drängst weiter. Es lastet auf dir — aber heute Nacht musst du wählen, und wieder wählen.",
63: "Du bringst ihn sicher zur Hütte zurück, wo seine Freunde vor Erleichterung aufschreien. Man wickelt dich in einen trockenen Mantel und macht dir Platz am Ofen. »Danke«, sagen sie immer wieder. Aber die Hütte wartet, und du kannst nicht bleiben.",
64: "Du blickst über den ganzen Berg — ganz weiß, ganz still. Der Schnee liegt bleich und tief im Dunkeln. Kein Licht irgendwo außer am Hang. Der ganze Berg scheint den Atem anzuhalten und auf den Morgen zu warten.",
65: "Die Kälte sinkt auf ihren Tiefpunkt. Das Barometer fällt so tief es geht, und dein Atem hängt weiß in der stillen Luft. Schwer zu denken, zu rühren, dir etwas daraus zu machen. Es ist die härteste Stunde der ganzen Nacht.",
67: "Der alte Doune drückt dir die letzte trockene Lampe in die Hand. »Fürs Fenster«, sagt er. »Geh — ich bleibe hier bei Marta und am Funk.« Sein Gesicht grau vor Sorge. Das ist die Hilfe, die er heute Nacht geben kann, und er gibt sie von Herzen.",
68: "Am Brennstofflager stürzt man sich auf die Kanister — Stimmen steigen, Hände greifen, Angst breitet sich schnell aus. Ein Stoß mehr, und es wird eine Schlägerei. Du kannst versuchen, sie zu beruhigen und gerecht zu teilen. Oder deinen nehmen und gehen.",
69: "Ein schneeverstopftes Biwak umschließt dich — weiß, still, tiefe Kälte, ein Ort, wo nichts lebendig scheint. Dann hörst du es: ein Atem, schwach und nah, unter dem Schnee. Jemand ist hier doch am Leben.",
70: "Weit draußen am Hang hebt und senkt sich ein kleines Licht. Wo heute Nacht niemand sein sollte — es zeigt sich, verschwindet, zeigt sich wieder. Niemand kann es erklären. Und etwas in dir will hinausgehen und antworten.",
71: "Du gehst auf den Hang hinaus und rufst ins Dunkel. Nur der Wind antwortet. Dann siehst du es: eine kleine Gestalt im Schnee, halb im Weiß verborgen. Jemand ist doch draußen. Und er bewegt sich kaum.",
72: "Du erreichst ihn, und das Herz dreht sich dir um. Es ist ein junger Wanderer — Rowan — zusammengerollt im Schnee, halb erfroren, kaum wach. Die Kälte hat ihn. Keine Zeit zu warten. Du musst jetzt handeln.",
73: "Du rufst noch einmal ins Dunkel, und einen Moment nichts. Dann kommt eine dünne Stimme zurück, von der Kälte zerrissen: »Hier! Hier draußen!« Jemand ist am Hang, und er braucht Hilfe. Und er klingt gar nicht stark.",
74: "Du ziehst Rowan aus dem Schnee und wickelst ihn in deinen Mantel. Langsam kommt er zu sich, klammert sich an deinen Arm. »Die Lampe«, flüstert er. »Halte die Lampe im Fenster ...« Selbst jetzt, halb erfroren, denkt er an die Hütte.",
75: "Du drehst dich um, um Hilfe zu holen — und hältst jäh inne. Keine Hilfe hier draußen, nicht vor dem Morgen. Keine Mannschaft, kein Tal, niemand. Du oder niemand, und Rowan weiß es auch. Seine ängstlichen Augen folgen dir im Dunkel.",
76: "Rowan blickt auf, die Augen klarer. »Die Hüttenwartin, Marta — das ist meine Oma«, sagt er. »Wir reden nicht. Nicht, seit mein Vater und sie sich zerstritten. Eine lange, traurige Geschichte.« Und du hörst, wie lang sie ist.",
77: "Du beschließt, sie vor dem Morgen zusammenzubringen — Rowan und die alte Marta, nach all den Jahren. Eine Kleinigkeit neben dem Sturm und der Kälte. Aber nicht nichts. Manche verschlossenen Türen lassen sich noch öffnen.",
78: "Die kleine Gestalt rührt sich nicht, und die Kälte arbeitet an ihr, langsam und geduldig. Und doch kam jemand ganz hierher, ins Dunkel, allein. Du kannst ihn nicht liegen lassen. Du musst näher und wissen, wer es ist.",
79: "Du gehst näher und erkennst ihn sofort. Es ist Rowan — das Enkelkind der alten Marta, seit Jahren nicht hier gesehen, seit dem Zerwürfnis der Familie. Dann kommt ein schwacher Laut aus dem Schnee, zu deinen Füßen. Jetzt machst du schnell.",
80: "Vane kommt ein letztes Mal, die Laterne schwingend. »Immer noch am Kämpfen?«, sagt er. »Lass die Kälte sie holen. Letzte Chance, auf der Siegerseite zu stehen, Freund.« Dasselbe leichte Lächeln. Dieselbe alte Lüge.",
90: "Du bist zurück in der Hütte, durchfroren, die härteste Kälte der Nacht lastet auf allem. An der Leiter liegt Marta grau und still. Der Ofen brennt niedrig, das Fenster trüb. Das ist die Stunde, in der sich alles entscheidet.",
91: "Du erreichst den Ofen: die Flamme niedrig, das Fenster erloschen. Am Hang ist die Kälte nahe daran, jeden zu holen, der noch draußen ist. Du musst den Ofen wieder voll und die Lampe hell bekommen — und zwar jetzt, schnell.",
92: "Dann erreicht dich endlich Hilfe — mehr Hände, mehr Brennstoff, feste Leute, die die Arbeit kennen. Du bist nicht mehr allein damit; andere teilen die Last. Es ist, als setzte man etwas Schweres ab, das man viel zu lange getragen hat.",
93: "Jetzt hältst du die Hütte warm und hell — und was du tun kannst, hängt davon ab, was du mitgebracht hast. Mit richtigem Brennstoff hast du genug zum Arbeiten. Ohne ihn musst du jeden letzten Funken Flamme hegen. So oder so ist die Nacht lange nicht vorbei.",
94: "Du gehst nach Marta sehen, und ihre Augen öffnen sich ein wenig. Angst darin — dann, als sie dich sieht, ein wenig weniger. »Du hast es gehalten«, flüstert sie. »Das hab ich«, sagst du leise. »Jetzt ruh dich aus.«",
95: "Der Brennstoff schafft es. Du fütterst den Ofen und kürzt den Docht, und die Flamme kommt voll und golden hoch. Das Fenster brennt hell gegen den Sturm. Warmes Licht, das all die Kälte zurückdrängt. Das, denkst du, war der Sinn der ganzen harten Nacht.",
96: "Kein richtiger Brennstoff zum Eingießen: du hegst die wenige Flamme, die bleibt. Du schirmst sie mit deinem Körper vom Zug ab, fütterst sie mit Fetzen, Atem, purem Willen. Sie brennt niedrig und dünn. Vielleicht reicht es nicht. Aber du lässt sie nicht kampflos sterben.",
97: "Die Flamme ist niedrig und versagt, und du fürchtest, sie allein zu schirmen reicht nicht. Du hast alles getan mit dem, was du hattest. Aber sie hält vielleicht nicht. Du brauchst mehr — mehr Brennstoff, mehr Hände, oder beides.",
98: "Du blickst hinaus und siehst es. Weit draußen am Hang flammt ein Licht auf und fällt — wo niemand sein sollte, zeigt sich und verbirgt sich. Es zieht dein Auge. Und etwas Tieferes.",
99: "Das Licht am Hang zeigt sich wieder — wo alle schwören, dass niemand wäre. Aber ein Licht bedeutet eine Hand, und eine Hand bedeutet einen Menschen. Einen Menschen, draußen, allein, in solch einer Kälte.",
100: "Dann kommt die lange Wache: du fütterst den Ofen, hältst Marta warm, wachst über die Kälte Stunde um Stunde. Nichts Aufregendes — nur stete, harte, sorgfältige Arbeit. Aber es ist die ganze Arbeit heute Nacht, und sie ist deine.",
101: "Und dann, endlich, wendet es sich. Der Wind lockert ein wenig seinen Griff. Der Himmel wird grau am Rand des Grats, und das erste dünne Licht kommt. Die Kälte verliert. Du hast die Nacht fast gehalten.",
102: "Das ist die härteste Stunde, kurz vor dem Umschwung. Die Kälte ist noch nicht gewichen; die Arme schmerzen, die Augen brennen. Aber du spürst die Nacht sich wenden, irgendwo darunter. Halte noch ein wenig durch.",
103: "Auf dem Hügel siehst du sie — Fackeln, dunkle Gestalten, niedrige Feuer gegen den Schnee. Andere Leute, draußen in der Kälte wie du. Auch das Tal kam durch diese Nacht. Du warst nie so allein, wie du dich fühltest.",
104: "Endlich kommt Hilfe den Hügel herauf — die Mannschaft, mehr Hände, mehr Brennstoff, echte Hilfe in gutem Tempo. Du lehnst an der Tür und siehst sie kommen, die Beine zittern. Aber das Schlimmste der Nacht liegt hinter dir.",
105: "Der Morgen steigt über den Berg, das Licht wird grau, dann blass und klar. Die Sonne steigt über den Grat, und die Kälte lässt los. Die Lampe brennt noch im Fenster. Das Schlimmste ist endlich vorbei.",
106: "Dann kommt er — der erste Vogel des Morgens, der über den Schnee ruft, als hätte es keinen Sturm gegeben. Nach der Nacht, die du hattest, wirkt es fast absurd. Und es ist schön, und du hältst inne, um zu lauschen.",
107: "Vom Fenster aus spähst du zum Hang, wo ein Licht sich hebt, fällt und langsam wächst. Endlich kommt etwas, noch zu weit, um es zu erkennen. Aber ein Licht bedeutet jemanden — und jemand ist heute Nacht weit besser als niemand.",
110: "Das erste Licht kommt endlich, und die Nacht rechnet sich zusammen. Alles, was du draußen in der Kälte getan hast, kommt jetzt zu dir zurück — manches zum Stolzsein, manches nicht. Sehen wir also, worauf es alles hinauslief.",
111: "Die Nacht summiert sich — nicht mit einer großen Tat, sondern mit vielen kleinen. Was du gehalten, was du verweigert hast, für wen du in die Kälte gingst. Alles zählt am Ende. Alles machte die Nacht zu dem, was sie war.",
112: "Es gibt mehr abzuwägen; die Nacht barg anderes. Ein Fremder, für den du anhieltest. Ein Mantel und eine Lampe, mit offener Hand verschenkt. Kleine Entscheidungen, in der Kälte getroffen, als es leichter gewesen wäre, vorbeizugehen.",
113: "Und was lässt dir die Nacht? Vielleicht keinen sauberen Sieg. Vielleicht nur dies: dass du hinausgingst, dass du es versuchtest. Als es dunkel, kalt und leicht war, die Tür zu verriegeln, tatst du es nicht. Das zählt.",
114: "Aber nicht jede Nacht endet gut. Manche Entscheidungen kosten mehr, als du wusstest; manche Türen lassen sich, einmal geöffnet, nicht mehr schließen. Das ist das harte Ende der Nacht — wo das Schlimmste zu dir zurückkommt.",
120: "Du hast den Ofen am Ziehen und die Lampe hell im Fenster die ganze Nacht gehalten. Beim ersten Licht hebt sich die Wolke über dem Grat, die Mannschaft erreicht dich, und jeder, den der Berg heute Nacht hielt, wird warm durchgebracht. Alles kam durch, weil du aufblieb­st und das Licht nicht sterben ließt. Das ist alles.",
121: "Du hast dem Licht geantwortet, das niemand erklären konnte. Du fandest Rowan verloren und erfroren unter der Wächte und brachtest ihn gerade rechtzeitig herein und ins Warme. Und mehr als ein Leben wurde gerettet: Rowan ist Martas Enkelkind. Eine jahrelang verschlossene Tür öffnet sich wieder, im Grau des Morgens.",
122: "Es gab keine einzelne Heldentat — es gab etwas Besseres. Du machtest aus einem schlafenden Tal Menschen mit Fackeln auf dem Hügel, und zusammen brachten sie die Nacht durch. Niemand blieb darin allein. Das, am Ende, kann ein Tal sein.",
123: "Du hast den Betrug verweigert — sahst Vanes Trick und kehrtest ihm den Rücken. Du bewahrtest den Kopf und hieltest die Hütte mit anständigen Mitteln. Keine perfekte Nacht; du hast nicht alle durchgebracht. Aber sauber, und sauber genügt.",
124: "Du hast es nicht ganz gehalten. Aber der Wanderer, für den du anhieltest, kommt jetzt zurück. Er hilft dir, die Hütte zu halten und Marta zu wärmen. Nicht der volle Sieg. Aber eine Güte, so zeigt sich, kommt zurück.",
125: "Du hast deinen Mantel und deinen Brennstoff an Ärmere gegeben und beendest die Nacht selbst durchfroren. Du hast nicht alles gerettet. Aber du bist nicht allein, und niemand, dem du begegnetest. Etwas im Tal hat sich verschoben. Es ist ein Anfang, keine Rettung.",
126: "Du kommst knapp durch. Der Wind legt sich endlich, und ein dünner Morgen bringt die Mannschaft den Hügel herauf. Kein Triumph, und niemand wird davon singen. Aber du kamst durch die Nacht — und das ist am Ende eine Erleichterung für sich.",
127: "Du hast nicht alle durchgebracht. Aber das Tal sah dich auf dem Hügel, als andere ihre Türen verriegelten — sah dich es versuchen, in der schlimmsten Nacht des Jahres. Von heute an bist du jemand, den dieser Ort kennt. Und das ist nicht nichts.",
128: "Du nahmst Vanes Handel an, und am Morgen ist die Hütte für unbewohnbar erklärt — niemandes mehr. Die Kälte tat den Rest. Das Geld in deiner Tasche ist kalt, und das Fenster ist dunkel. Du wirst nicht so bald vergessen, wie du es verdient hast.",
129: "Die Wächte war eine Falle, genau wie Doune gewarnt hatte. Sie brach unter dir im Dunkeln, und sie nahm die ganze Nacht. Du schleppst dich heraus, verletzt und erfroren, und erreichst die andere Seite viel zu spät. Die Wächte kostete dich alles, was die Abkürzung versprach.",
130: "Du verbrachtest die Nacht mit den falschen Dingen, und der Ofen blieb zu lange dunkel. Beim Morgen ist die Hütte kalt, und wer am Hang war, wurde nicht rechtzeitig gefunden. Du gingst zwar in die Kälte hinaus. Aber du hieltest das Licht nicht, als es wirklich zählte.",
131: "Am Ende bliebst du drinnen, wo es warm und sicher war. Du sagtest dir, der Sturm sei zu hart, es sei nicht deine Sache, Hilfe käme im Morgengrauen. Alles davon war wahr. Und die ganze Nacht, draußen, blieb das Fenster dunkel. Dir ist nichts Schlimmes passiert. Du wirst lange, lange daran denken.",
}
def main():
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    data = json.load(open(OUT, encoding="utf-8")) if os.path.exists(OUT) else {}
    a = 0
    for nid, t in G.items():
        k = str(nid)
        if k not in data: a += 1
        data[k] = t
    data = {k: data[k] for k in sorted(data, key=lambda x: int(x))}
    json.dump(data, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("the-refuge/de.json: %d (+%d)" % (len(data), a))
if __name__ == "__main__":
    main()
